/bin/bash -lc 'set -eu
case_root="$PWD"
case_dir="$(mktemp -d "$case_root/.review.XXXXXXXX")"
trap '"'cd \""'$case_root"; find "$case_dir" -depth -delete'"' EXIT
cp -R \""'$case_root/release/." "$case_dir/"
cd "$case_dir"
npm install --offline --ignore-scripts --no-audit --no-fund --cache "$case_dir/npm-cache" "$case_root/vendor/hono-4.13.19.tgz"
npm test --cache "$case_dir/npm-cache"
node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import app from './app.mjs';

const framework = JSON.parse(readFileSync('./node_modules/hono/package.json', 'utf8'));
assert.equal(framework.version, '4.13.19');
console.log(JSON.stringify({ node: process.version, hono: framework.version }));

const scenarios = [
  { id: 'k8', shift: 'day', status: 200, body: { id: 'k8', title: 'River' }, steps: 'dispatch,session,read' },
  { id: 'k8', status: 401, body: { error: 'sign_in' }, steps: 'dispatch,session' },
  { id: 'missing', shift: 'day', status: 404, body: { error: 'not_found' }, steps: 'dispatch,session,read' },
  { id: 'm3', shift: 'day', status: 502, body: { error: 'invalid_record' }, steps: 'dispatch,session,read,error' },
];

let failures = 0;
for (const { id, shift, status, body, steps } of scenarios) {
  const path = '/desk/' + id;
  const response = await app.request(path, { method: 'GET', headers: shift ? { 'x-shift': shift } : {} });
  assert.ok(response instanceof Response);
  const actual = {
    status: response.status,
    body: await response.json(),
    steps: response.headers.get('x-desk-steps'),
  };
  const expected = { status, body, steps };
  const differences = Object.keys(expected).filter(key => {
    try {
      assert.deepEqual(actual[key], expected[key]);
      return false;
    } catch {
      return true;
    }
  });
  failures += Number(differences.length > 0);
  console.log(JSON.stringify({ path, shift: shift ?? null, contentType: response.headers.get('content-type'), expected, actual, differences }));
}
console.log(JSON.stringify({ scenarios: scenarios.length, passed: scenarios.length - failures, failed: failures }));
process.exitCode = Number(failures > 0);
NODE"

